package mysqlexpr

import "strings"

// QualifiedIdent is one name from a DROP TABLE list.
// Schema is empty when the statement did not qualify the name.
type QualifiedIdent struct {
	Schema string
	Table  string
}

// ParseDropTable reads DROP [TEMPORARY] TABLE[S] [IF EXISTS] name [, name] ...
// [RESTRICT | CASCADE]. A name is [schema .] table, backquoted or bare.
// A doubled backtick inside a quoted name is one backtick. Whitespace,
// newlines, and plain comments (including /* generated by server */) are
// skipped. An executable comment, a double-quoted name, an unterminated
// quote or comment, or a second statement is not ok.
// isDrop is false when sql is not this statement.
func ParseDropTable(sql string) (names []QualifiedIdent, isDrop, ok bool) {
	p := &dropCur{s: sql}
	word, good := p.ident()
	if !good || p.quoted || p.bad || !strings.EqualFold(word, "DROP") {
		return nil, false, false
	}
	word, good = p.ident()
	if p.bad {
		return nil, false, false
	}
	if good && !p.quoted && strings.EqualFold(word, "TEMPORARY") {
		word, good = p.ident()
		if p.bad {
			return nil, false, false
		}
	}
	if !good || p.quoted || (!strings.EqualFold(word, "TABLE") && !strings.EqualFold(word, "TABLES")) {
		return nil, false, false
	}
	if !p.ifExists() || p.bad {
		return nil, true, false
	}
	for {
		name, good := p.qualified()
		if !good || p.bad {
			return nil, true, false
		}
		names = append(names, name)
		p.skip()
		if p.bad {
			return nil, true, false
		}
		if p.i < len(p.s) && p.s[p.i] == ',' {
			p.i++
			continue
		}
		break
	}
	if !p.trailing() || p.bad || len(names) == 0 {
		return nil, true, false
	}
	return names, true, true
}

type dropCur struct {
	s      string
	i      int
	bad    bool
	quoted bool
}

func (p *dropCur) skip() {
	if p.bad {
		return
	}
	for p.i < len(p.s) {
		switch p.s[p.i] {
		case ' ', '\t', '\n', '\r', '\f', '\v':
			p.i++
		case '#':
			for p.i < len(p.s) && p.s[p.i] != '\n' {
				p.i++
			}
		case '-':
			if p.i+1 < len(p.s) && p.s[p.i+1] == '-' && (p.i+2 >= len(p.s) || p.s[p.i+2] == ' ' || p.s[p.i+2] == '\t' || p.s[p.i+2] == '\n' || p.s[p.i+2] == '\r') {
				for p.i < len(p.s) && p.s[p.i] != '\n' {
					p.i++
				}
				continue
			}
			return
		case '/':
			if p.i+1 < len(p.s) && p.s[p.i+1] == '*' {
				if p.i+2 < len(p.s) && (p.s[p.i+2] == '!' || (p.s[p.i+2] == 'M' && p.i+3 < len(p.s) && p.s[p.i+3] == '!')) {
					p.bad = true
					return
				}
				end := strings.Index(p.s[p.i+2:], "*/")
				if end < 0 {
					p.bad = true
					return
				}
				p.i += 2 + end + 2
				continue
			}
			return
		default:
			return
		}
	}
}

func (p *dropCur) ident() (string, bool) {
	p.skip()
	p.quoted = false
	if p.bad || p.i >= len(p.s) {
		return "", false
	}
	if p.s[p.i] == '"' || p.s[p.i] == '\'' {
		p.bad = true
		return "", false
	}
	if p.s[p.i] == '`' {
		p.quoted = true
		var b strings.Builder
		p.i++
		for p.i < len(p.s) {
			if p.s[p.i] == '`' {
				if p.i+1 < len(p.s) && p.s[p.i+1] == '`' {
					b.WriteByte('`')
					p.i += 2
					continue
				}
				p.i++
				return b.String(), true
			}
			b.WriteByte(p.s[p.i])
			p.i++
		}
		p.bad = true
		return "", false
	}
	if !dropIdentByte(p.s[p.i]) || (p.s[p.i] >= '0' && p.s[p.i] <= '9') {
		return "", false
	}
	start := p.i
	p.i++
	for p.i < len(p.s) && dropIdentByte(p.s[p.i]) {
		p.i++
	}
	return p.s[start:p.i], true
}

func dropIdentByte(c byte) bool {
	return c == '_' || c == '$' || c >= 0x80 || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')
}

func (p *dropCur) qualified() (QualifiedIdent, bool) {
	first, ok := p.ident()
	if !ok {
		return QualifiedIdent{}, false
	}
	p.skip()
	if p.bad {
		return QualifiedIdent{}, false
	}
	if p.i < len(p.s) && p.s[p.i] == '.' {
		p.i++
		second, ok := p.ident()
		if !ok {
			return QualifiedIdent{}, false
		}
		return QualifiedIdent{Schema: first, Table: second}, true
	}
	return QualifiedIdent{Table: first}, true
}

func (p *dropCur) ifExists() bool {
	save := p.i
	word, ok := p.ident()
	if p.bad {
		return false
	}
	if !ok || p.quoted || !strings.EqualFold(word, "IF") {
		p.i = save
		return true
	}
	word, ok = p.ident()
	return ok && !p.quoted && strings.EqualFold(word, "EXISTS") && !p.bad
}

func (p *dropCur) trailing() bool {
	save := p.i
	word, ok := p.ident()
	if p.bad {
		return false
	}
	if ok && !p.quoted && (strings.EqualFold(word, "RESTRICT") || strings.EqualFold(word, "CASCADE")) {
		save = p.i
	} else {
		p.i = save
	}
	p.skip()
	if p.bad {
		return false
	}
	if p.i < len(p.s) && p.s[p.i] == ';' {
		p.i++
		p.skip()
	}
	return !p.bad && p.i >= len(p.s)
}
